package com.cinemahub.uploader
import android.Manifest
import android.app.*
import androidx.activity.ComponentActivity
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.view.ViewGroup
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
class MainActivity:ComponentActivity(){
 private val prefs by lazy{getSharedPreferences("cinemahub",MODE_PRIVATE)}
 private lateinit var root:LinearLayout;private lateinit var status:TextView;private var picked:Uri?=null
 private val picker=registerForActivityResult(ActivityResultContracts.OpenDocument()){u->if(u!=null){try{contentResolver.takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:Exception){};picked=u;status.text="Video selected."}}
 override fun onCreate(b:Bundle?){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),7);if(prefs.getString("token",null).isNullOrBlank())login()else uploader()}
 private fun page(t:String){root=LinearLayout(this).apply{orientation=1;setPadding(22,26,22,24);setBackgroundColor(0xff101016.toInt())};val s=ScrollView(this);s.addView(root);setContentView(s);root.addView(TextView(this).apply{text="C I N E M A H U B";setTextColor(0xffe8bd72.toInt())});root.addView(TextView(this).apply{text=t;textSize=26f;setTextColor(-1);setPadding(0,18,0,12)});status=TextView(this).apply{setTextColor(0xffffd18a.toInt());setPadding(0,10,0,10)}}
 private fun edit(h:String)=EditText(this).apply{hint=h;setTextColor(-1);setHintTextColor(0xffaaaaaa.toInt());setPadding(18,8,18,8);setBackgroundColor(0xff25252d.toInt());layoutParams=LinearLayout.LayoutParams(-1,ViewGroup.LayoutParams.WRAP_CONTENT).apply{bottomMargin=10}}
 private fun btn(t:String,f:()->Unit)=Button(this).apply{text=t;setOnClickListener{f()}}
 private fun login(){page("Creator sign in");val email=edit("Owner email");email.setText("satishmaske660@gmail.com");root.addView(email);val send=btn("Send one-time code"){};val handler=android.os.Handler(mainLooper);fun cooldown(seconds:Int){val until=System.currentTimeMillis()+seconds*1000L;prefs.edit().putLong("otp_cooldown_until",until).apply();send.isEnabled=false;fun tick(){val left=((until-System.currentTimeMillis()+999)/1000).toInt();if(left<=0){send.isEnabled=true;send.text="Send one-time code";status.text="You can request a new code now. Check your inbox and Spam first.";return};send.text="Try again in "+left+"s";status.text="Please wait before requesting another email code.";handler.postDelayed({tick()},1000)};tick()};val saved=prefs.getLong("otp_cooldown_until",0L);if(saved>System.currentTimeMillis())cooldown(((saved-System.currentTimeMillis()+999)/1000).toInt());send.setOnClickListener{val e=email.text.toString().trim().lowercase();if(e!="satishmaske660@gmail.com"){status.text="Email not authorised.";return@setOnClickListener};if(!send.isEnabled)return@setOnClickListener;send.isEnabled=false;send.text="Sending…";status.text="Sending one-time code…";Thread{try{Api.call("POST","/auth/v1/otp","""+"{\"email\":\"$e\",\"create_user\":false}"+""" );runOnUiThread{send.isEnabled=true;send.text="Send another code";val code=edit("6-digit email code");AlertDialog.Builder(this).setTitle("Check your email").setMessage("Enter the code sent to "+e).setView(code).setPositiveButton("Verify"){_,_->verify(e,code.text.toString().trim())}.setNegativeButton("Cancel",null).show()}}catch(x:Exception){runOnUiThread{val msg=x.message?: "Unknown login error";if(msg.contains("429")||msg.contains("rate limit",true)||msg.contains("over_email_send_rate_limit")){status.text="Supabase has temporarily limited email codes. Check your inbox and Spam; wait before trying again.";cooldown(60)}else{status.text="Login error: "+msg;send.isEnabled=true;send.text="Try again"}}}}.start()};root.addView(send);root.addView(status)}
 private fun verify(e:String,code:String){Thread{try{val r=Api.call("POST","/auth/v1/verify","""{"email":"$e","token":"$code","type":"email"}""");prefs.edit().putString("token",org.json.JSONObject(r).getString("access_token")).apply();runOnUiThread{uploader()}}catch(x:Exception){runOnUiThread{status.text="Verification failed: "+x.message}}}.start()}
 private fun uploader(){page("Video uploader");root.addView(TextView(this).apply{text="Signed in as satishmaske660@gmail.com";setTextColor(-1)});val cat=Spinner(this);cat.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Movies","Series","Content"));root.addView(cat);val title=edit("Movie / series / video title");root.addView(title);val desc=edit("Description (optional)");root.addView(desc);val subtype=Spinner(this);subtype.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Short Film","Behind the Scenes","Trailer","Music Video","Bonus Video","Other"));root.addView(TextView(this).apply{text="Content type";setTextColor(-1)});root.addView(subtype);val season=edit("Season number");season.setText("1");root.addView(season);val ep=edit("Episode number");ep.setText("1");root.addView(ep);val epname=edit("Episode name");root.addView(epname);root.addView(btn("Choose video"){picker.launch(arrayOf("video/*"))});root.addView(btn("Start background upload"){val u=picked;if(u==null){status.text="Choose a video first.";return@btn};if(title.text.isBlank()){status.text="Enter a title.";return@btn};val kind=listOf("movie","series","content")[cat.selectedItemPosition];val i=Intent(this,UploadService::class.java).apply{action=UploadService.ACTION;putExtra("uri",u.toString());putExtra("title",title.text.toString());putExtra("description",desc.text.toString());putExtra("kind",kind);putExtra("subtype",subtype.selectedItem.toString());putExtra("season",season.text.toString().toIntOrNull()?:1);putExtra("episode",ep.text.toString().toIntOrNull()?:1);putExtra("episodeTitle",epname.text.toString())};if(Build.VERSION.SDK_INT>=26)startForegroundService(i)else startService(i);status.text="Upload started. Check the notification."});root.addView(btn("Sign out"){prefs.edit().remove("token").apply();login()});root.addView(status)}
}
